executionCode:
return {
  name: node.properties.toolName?.value || 'calculate',
  description: node.properties.toolDescription?.value || 'Perform math calculations',
  enabled: node.properties.enabled?.value !== false,
  schema: {
    type: 'object',
    properties: {
      expression: {
        type: 'string',
        description: 'Mathematical expression to evaluate (e.g., "2 + 2", "sqrt(16)", "sin(PI/2)")'
      }
    },
    required: ['expression']
  },
  code: `const mathjs = require('mathjs');
try {
  const result = mathjs.evaluate(args.expression);
  return { expression: args.expression, result };
} catch (error) {
  throw new Error(\`Calculation error: \${error.message}\`);
}`
};
